+fn fit_text(library: &Library, value: &str, initial_size: u32, width: i32) -> Result<Text> {
+    let mut size = initial_size.max(1);
+    loop {
+        let shaped = text(&font(library, size)?, value)?;
+        if shaped.advance <= f64::from(width) || size == 1 {
+            return Ok(shaped);
+        }
+        size -= 1;
+    }
+}
